def nth_combination_with_replacement(iterable, r, index):
    """Equivalent to ``list(combinations_with_replacement(iterable, r))[index]``

    The subsequences of *iterable* that are of length *r* with replacement
    can be ordered lexicographically. :func:`nth_combination_with_replacement`
    computes the subsequence at sort position *index* directly, without
    computing the previous subsequences.

        >>> nth_combination_with_replacement('abcdefg', 3, 10)
        ('a', 'd', 'f')

    ``ValueError`` will be raised if *r* is negative.
    ``IndexError`` will be raised if the given *index* is invalid.
    """
    pool = tuple(iterable)
    n = len(pool)
    if r < 0:
        raise ValueError
    if r == 0:
        if index == 0:
            return tuple()
        raise IndexError

    # Compute total number of combinations with replacement: C(n + r - 1, r)
    c = 1
    for i in range(1, r + 1):
        c = c * (n + i - 1) // i

    if index < 0:
        index += c

    if not 0 <= index < c:
        raise IndexError

    result = []
    for i in range(r):
        # For each position, find which element to pick
        for j, item in enumerate(pool):
            # Number of ways to fill remaining positions from current element onward
            remaining_slots = r - i - 1
            remaining_elements = n - j
            if remaining_slots == 0:
                count = 1
            else:
                count = 1
                for k in range(1, remaining_slots + 1):
                    count = count * (remaining_elements + k - 1) // k
            if index < count:
                result.append(item)
                pool = pool[j:]  # Restrict to elements from current position onward
                n = len(pool)
                break
            index -= count

    return tuple(result)
